 </style>
 </head>
 <body><main id="game" aria-label="Ashwing game"><canvas id="c"></canvas><div class="vignette"></div><div class="topline"><div class="brand">✦ <b>ASHWING</b> / THE HOLLOW BELOW</div><div id="depth">DESCENT 01</div></div><div class="hud hidden" id="hud"><div class="bossbox"><div class="bossname" id="bossName">THE ASHEN WARDEN</div><div class="bar"><div class="fill" id="bossFill"></div></div></div><div class="playerbox"><div class="smallcap">VITALITY</div><div class="hearts" id="hearts">♥ ♥ ♥</div><div class="souls" id="souls">◈ 0 ECHOES</div></div></div><div class="toast" id="toast"></div><section class="overlay" id="overlay"><div class="card"><div class="eyebrow" id="eyebrow">A CAVERN-BORN NIGHTMARE</div><h1 class="title" id="title">ASHWING<span>THE HOLLOW BELOW</span></h1><p class="copy" id="copy">A fallen knight, a bottomless cave, and ancient things that should have stayed asleep. <span class="gold">Flap through the dark. Face the bosses. Find the way below.</span></p><button class="button" id="start">DESCEND</button><div class="hint" id="hint">SPACE / TAP TO FLAP &nbsp; · &nbsp; X / ATTACK TO STRIKE</div></div></section><div class="mobile-controls" id="mobile"><button class="touchbtn" id="flap">FLAP</button><button class="touchbtn" id="attack">STRIKE</button></div></main>
 <script>
+(()=>{
+const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');
+const ui={overlay:document.getElementById('overlay'),hud:document.getElementById('hud'),start:document.getElementById('start'),title:document.getElementById('title'),eyebrow:document.getElementById('eyebrow'),copy:document.getElementById('copy'),hint:document.getElementById('hint'),bossName:document.getElementById('bossName'),bossFill:document.getElementById('bossFill'),hearts:document.getElementById('hearts'),souls:document.getElementById('souls'),depth:document.getElementById('depth'),toast:document.getElementById('toast')};
+let W=960,H=600,dpr=1,last=0,elapsed=0,toastTimer=0;
+function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0)}
+new ResizeObserver(resize).observe(canvas);resize();
+const names=['THE ASHEN WARDEN','THE GUTTER WYRM','THE HOLLOW KING'];
+const titles=['Ashen Warden','Gutter Wyrm','Hollow King'];
+const palette=[['#947263','#4b3b40','#d87854'],['#687d78','#2e4548','#75c8a9'],['#aaa084','#55445a','#d2a7f2']];
+let game={mode:'menu',time:0,scroll:0,player:{x:W*.28,y:H*.5,vy:0,r:14,hp:3,inv:0,flap:0},boss:{hp:8,max:8,x:W*.79,y:H*.5,phase:0,shot:2.4,hit:0},obstacles:[],shots:[],enemyShots:[],sparks:[],distance:0,echoes:0,stage:0,spawn:0};
+function reset(){game={mode:'play',time:0,scroll:0,player:{x:W*.27,y:H*.5,vy:0,r:13,hp:3,inv:0,flap:0},boss:{hp:8,max:8,x:W*.79,y:H*.5,phase:0,shot:2.1,hit:0},obstacles:[],shots:[],enemyShots:[],sparks:[],distance:0,echoes:0,stage:0,spawn:.8};ui.overlay.classList.add('hidden');ui.hud.classList.remove('hidden');ui.depth.textContent='DESCENT 01';syncHud();flap()}
+function showOverlay(type){game.mode=type;ui.overlay.classList.remove('hidden');ui.hud.classList.add('hidden');if(type==='menu'){ui.eyebrow.textContent='A CAVERN-BORN NIGHTMARE';ui.title.innerHTML='ASHWING<span>THE HOLLOW BELOW</span>';ui.copy.innerHTML='A fallen knight, a bottomless cave, and ancient things that should have stayed asleep. <span class="gold">Flap through the dark. Face the bosses. Find the way below.</span>';ui.start.textContent='DESCEND';ui.hint.textContent='SPACE / TAP TO FLAP  ·  X / ATTACK TO STRIKE'}else if(type==='dead'){ui.eyebrow.textContent='YOUR LIGHT FADES';ui.title.innerHTML='YOU FELL<span>THE CAVE REMEMBERS</span>';ui.copy.innerHTML=`You gathered <span class="gold">${game.echoes} echoes</span> before the dark took you. The old ones are still waiting.`;ui.start.textContent='RISE AGAIN';ui.hint.textContent='PRESS ENTER OR TAP TO RETURN'}else{ui.eyebrow.textContent='THE DEPTHS ARE QUIET';ui.title.innerHTML='HOLLOW NO MORE<span>THE LAST EMBER ENDURES</span>';ui.copy.innerHTML=`The Hollow King is gone. <span class="gold">You carried ${game.echoes} echoes into the deep.</span> The cave has no more masters.`;ui.start.textContent='DESCEND AGAIN';ui.hint.textContent='PRESS ENTER OR TAP TO PLAY AGAIN'}}
+function syncHud(){ui.bossName.textContent=names[game.stage]||names[2];ui.bossFill.style.width=Math.max(0,game.boss.hp/game.boss.max*100)+'%';ui.hearts.textContent=Array.from({length:3},(_,i)=>i<game.player.hp?'♥':'♡').join(' ');ui.souls.textContent='◈ '+game.echoes+' ECHOES'}
+function announce(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1500)}
+function flap(){if(game.mode!=='play')return;game.player.vy=-H*.48;game.player.flap=.28;burst(game.player.x-7,game.player.y+4,'#e3b46e',4)}
+function attack(){if(game.mode!=='play')return;const p=game.player;game.shots.push({x:p.x+15,y:p.y,vx:W*.8,life:1.6});burst(p.x+14,p.y,'#f2d69b',5)}
+function pressFlap(){if(game.mode==='menu'||game.mode==='dead'||game.mode==='win'){if(game.mode!=='play')reset();return}flap()}
+document.getElementById('start').addEventListener('click',()=>reset());
+document.getElementById('flap').addEventListener('pointerdown',e=>{e.preventDefault();pressFlap()});
+document.getElementById('attack').addEventListener('pointerdown',e=>{e.preventDefault();attack()});
+canvas.addEventListener('pointerdown',e=>{if(game.mode!=='play'){reset();return}const r=canvas.getBoundingClientRect(),x=e.clientX-r.left;if(x>W*.68)attack();else flap()});
+window.addEventListener('keydown',e=>{if(['Space','ArrowUp','KeyW'].includes(e.code)){e.preventDefault();if(game.mode!=='play')reset();else flap()}if(['KeyX','KeyJ','Enter'].includes(e.code)){if(game.mode==='play')attack();else reset()}});

