function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=25+Math.random()*150;game.sparks.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,color,size:1+Math.random()*2.5})}}
function spawnObstacle(){const gap=H*.37,margin=H*.13,cy=margin+Math.random()*(H-2*margin);game.obstacles.push({x:W+55,w:45,top:cy-gap/2,bottom:cy+gap/2,seed:Math.random()*100})}
function hitPlayer(){const p=game.player;if(p.inv>0)return;p.hp--;p.inv=1.35;p.vy=-H*.34;burst(p.x,p.y,'#d26055',13);syncHud();if(p.hp<=0){setTimeout(()=>showOverlay('dead'),450)}}
function collideCircleRect(cx,cy,r,x,y,w,h){const nx=Math.max(x,Math.min(cx,x+w)),ny=Math.max(y,Math.min(cy,y+h));return (cx-nx)**2+(cy-ny)**2<r*r}
function update(dt){game.time+=dt;const p=game.player,b=game.boss;if(game.mode!=='play')return;
 p.vy+=H*1.18*dt;p.y+=p.vy*dt;p.flap=Math.max(0,p.flap-dt);p.inv=Math.max(0,p.inv-dt);game.scroll+=dt*145;game.distance+=dt*18;game.spawn-=dt;
 if(game.spawn<=0){spawnObstacle();game.spawn=2.05+Math.random()*.55}
 for(const o of game.obstacles){o.x-=W*.34*dt;if(collideCircleRect(p.x,p.y,p.r,o.x,0,o.w,o.top)||collideCircleRect(p.x,p.y,p.r,o.x,o.bottom,o.w,H-o.bottom))hitPlayer()}
 game.obstacles=game.obstacles.filter(o=>o.x+o.w>-5);
 b.x=W*.78+Math.sin(game.time*.55)*W*.025;b.phase+=dt;b.y=H*.5+Math.sin(game.time*1.05+game.stage)*H*.22;b.hit=Math.max(0,b.hit-dt);b.shot-=dt;
 if(b.shot<=0){const dx=p.x-b.x,dy=p.y-b.y,d=Math.hypot(dx,dy)||1,speed=W*.26;game.enemyShots.push({x:b.x-22,y:b.y,vx:dx/d*speed,vy:dy/d*speed,life:4});b.shot=Math.max(.95,1.8-game.stage*.18)+Math.random()*.45}
 for(const s of game.shots){s.x+=s.vx*dt;s.life-=dt;if(Math.hypot(s.x-b.x,s.y-b.y)<47&&s.life>0){s.life=0;b.hp--;b.hit=.18;game.echoes+=4;burst(s.x,s.y,palette[game.stage][2],9);syncHud();if(b.hp<=0)defeatBoss()}}
 game.shots=game.shots.filter(s=>s.life>0&&s.x<W+50);
 for(const s of game.enemyShots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(Math.hypot(s.x-p.x,s.y-p.y)<p.r+9){s.life=0;hitPlayer()}}
 game.enemyShots=game.enemyShots.filter(s=>s.life>0&&s.x>-50&&s.x<W+50&&s.y>-50&&s.y<H+50);
 if(p.y-p.r<15||p.y+p.r>H-15)hitPlayer();
 if(Math.hypot(p.x-b.x,p.y-b.y)<45)hitPlayer();
 for(const s of game.sparks){s.x+=s.vx*dt;s.y+=s.vy*dt;s.vx*=.96;s.vy*=.96;s.life-=dt}game.sparks=game.sparks.filter(s=>s.life>0);
}
function defeatBoss(){game.stage++;game.echoes+=120;game.obstacles=[];game.enemyShots=[];syncHud();if(game.stage>=3){showOverlay('win');return}b.hp=b.max=8;game.spawn=2.3;game.player.hp=Math.min(3,game.player.hp+1);syncHud();announce(titles[game.stage-1]+' vanquished · +1 vitality');burst(b.x,b.y,'#e6b66e',28);game.depth=game.stage;ui.depth.textContent='DESCENT 0'+(game.stage+1)}

