function defeatBoss(){game.stage++;game.echoes+=120;game.obstacles=[];game.enemyShots=[];syncHud();if(game.stage>=3){showOverlay('win');return}b.hp=b.max=8;game.spawn=2.3;game.player.hp=Math.min(3,game.player.hp+1);syncHud();announce(titles[game.stage-1]+' vanquished · +1 vitality');burst(b.x,b.y,'#e6b66e',28);game.depth=game.stage;ui.depth.textContent='DESCENT 0'+(game.stage+1)}
function pathPoly(points,fill){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill()}
function drawBackground(){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#11131c');sky.addColorStop(.52,'#17151a');sky.addColorStop(1,'#0c1015');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 const glow=ctx.createRadialGradient(W*.5,H*.55,10,W*.5,H*.55,W*.67);glow.addColorStop(0,['#543626','#203b38','#392b48'][game.stage]);glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
 for(let layer=0;layer<3;layer++){const off=(game.scroll*(.13+layer*.17))%(W/5);ctx.beginPath();ctx.moveTo(0,0);for(let i=-1;i<7;i++){const x=i*W/5-off;const y=H*(.07+layer*.045)+Math.sin(i*2.7+layer)*H*.04;ctx.lineTo(x,y);ctx.lineTo(x+W*.09,y+H*(.09+layer*.025));ctx.lineTo(x+W*.15,y+H*.025)}ctx.lineTo(W,0);ctx.closePath();ctx.fillStyle=['#12151c','#101319','#0b0e13'][layer];ctx.fill();ctx.beginPath();ctx.moveTo(0,H);for(let i=-1;i<7;i++){const x=i*W/5+off;const y=H*(.92-layer*.025)+Math.sin(i*2.2+layer)*H*.035;ctx.lineTo(x,y);ctx.lineTo(x+W*.11,y-H*(.08+layer*.025));ctx.lineTo(x+W*.18,y-H*.02)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#15171a','#11151a','#0d1115'][layer];ctx.fill()}
 // drifting embers
 for(let i=0;i<34;i++){const x=(i*173+game.time*(18+i%4*5))%(W+20),y=(i*97+Math.sin(game.time+i)*22)%(H);ctx.globalAlpha=.18+(i%4)*.1;ctx.fillStyle=i%3?'#d89d61':'#9ed0b3';ctx.fillRect(x,y,1.5,1.5)}ctx.globalAlpha=1;
 // distant stone columns
 for(let i=0;i<8;i++){const x=((i*W/6-game.scroll*.12)%(W+100)+W+100)%(W+100)-30;ctx.fillStyle='#24242a';ctx.fillRect(x,H*.27,14,H*.46);ctx.fillStyle='#39343a';ctx.fillRect(x-5,H*.26,24,7);ctx.fillRect(x-3,H*.72,20,5)}
}
function drawObstacle(o){const w=o.w;const grad=ctx.createLinearGradient(o.x,0,o.x+w,0);grad.addColorStop(0,'#28252a');grad.addColorStop(.45,'#52423d');grad.addColorStop(1,'#211f24');ctx.fillStyle=grad;ctx.fillRect(o.x,0,w,o.top);ctx.fillRect(o.x,o.bottom,w,H-o.bottom);
 for(let j=0;j<5;j++){const xx=o.x+j*w/5;ctx.fillStyle=j%2?'#171a20':'#30292a';ctx.beginPath();ctx.moveTo(xx,0);ctx.lineTo(xx+w/5+3,0);ctx.lineTo(xx+w/5,o.top-10-(j%3)*7);ctx.lineTo(xx+w/10,o.top);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(xx,o.bottom);ctx.lineTo(xx+w/5,o.bottom+8+(j%3)*6);ctx.lineTo(xx+w/5+4,H);ctx.lineTo(xx,H);ctx.closePath();ctx.fill()}
 ctx.fillStyle='#a0785b';ctx.globalAlpha=.42;ctx.fillRect(o.x,o.top-3,w,3);ctx.fillRect(o.x,o.bottom,w,3);ctx.globalAlpha=1}
function drawPlayer(){const p=game.player;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.max(-.35,Math.min(.6,p.vy/H*.6)));if(p.inv>0&&Math.floor(game.time*14)%2)ctx.globalAlpha=.4;
 // ember trail
 ctx.fillStyle='#d89753';ctx.globalAlpha*=.3;ctx.beginPath();ctx.ellipse(-17,5,16,5,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=p.inv>0&&Math.floor(game.time*14)%2?.4:1;
 // wings
 ctx.fillStyle='#645044';ctx.beginPath();ctx.moveTo(-7,1);ctx.quadraticCurveTo(-25,-(p.flap?25:7),-27,-(p.flap?31:12));ctx.quadraticCurveTo(-10,-12,1,0);ctx.fill();ctx.strokeStyle='#c19a67';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-8,0);ctx.lineTo(-23,-(p.flap?24:7));ctx.stroke();
 // body and armor
 ctx.fillStyle='#282a31';ctx.beginPath();ctx.ellipse(0,2,14,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9c7854';ctx.beginPath();ctx.arc(4,-5,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d4c09a';ctx.beginPath();ctx.moveTo(-5,-10);ctx.lineTo(-14,-18);ctx.lineTo(0,-14);ctx.closePath();ctx.fill();ctx.fillStyle='#171c22';ctx.fillRect(6,-6,9,4);ctx.fillStyle='#f6d990';ctx.fillRect(11,-5,3,2);
 // sword
 ctx.strokeStyle='#d8d1b9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(9,3);ctx.lineTo(22,-6);ctx.stroke();ctx.strokeStyle='#b88d5a';ctx.beginPath();ctx.moveTo(12,5);ctx.lineTo(16,0);ctx.stroke();ctx.restore()}

